<?php
require_once __DIR__.'/includes/config.php'; require_login();require_permission('sales');
$uid=(int)$_SESSION['user_id']; $errors=[];
if ($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    $rawItems=$_POST['items']??[]; $customerId=($_POST['customer_id']??'')!==''?filter_var($_POST['customer_id'],FILTER_VALIDATE_INT):null;
    $paid=filter_var($_POST['amount_paid']??null,FILTER_VALIDATE_FLOAT); $method=$_POST['payment_method']??'cash'; $notes=trim($_POST['notes']??'');
    $items=[];
    if (!is_array($rawItems)) $errors[]='Invalid cart data.';
    else foreach($rawItems as $pid=>$qty) { $pid=filter_var((string)$pid,FILTER_VALIDATE_INT); $qty=filter_var($qty,FILTER_VALIDATE_INT); if($qty===false || $qty<1) continue; if(!$pid || $qty>100000) {$errors[]='Invalid product or quantity.';break;} $items[(int)$pid]=(int)$qty; }
    if(!$items) $errors[]='Add at least one product with a quantity greater than zero.';
    if($paid===false || $paid<0) $errors[]='Enter a valid amount paid.';
    if(!in_array($method,['cash','transfer','pos','credit','other'],true)) $errors[]='Choose a valid payment method.';
    if($customerId===false) $errors[]='Choose a valid customer.';
    if($method==='credit' && !$customerId) $errors[]='Select a customer for a credit sale.';
    if(!$errors) {
      try {
        $pdo->beginTransaction(); $total=0.0; $locked=[];
        $get=$pdo->prepare('SELECT id,name,selling_price,cost_price,quantity FROM products WHERE id=? AND user_id=? FOR UPDATE');
        foreach($items as $pid=>$qty){$get->execute([$pid,$uid]);$p=$get->fetch();if(!$p)throw new RuntimeException('One of the selected products was not found.');if((int)$p['quantity']<$qty)throw new RuntimeException('Insufficient stock for '.$p['name'].'. Available: '.$p['quantity']);$p['sale_qty']=$qty;$p['line_total']=(float)$p['selling_price']*$qty;$total+=$p['line_total'];$locked[]=$p;}
        if($customerId){$q=$pdo->prepare('SELECT id FROM customers WHERE id=? AND user_id=?');$q->execute([$customerId,$uid]);if(!$q->fetch())throw new RuntimeException('Customer not found.');}
        if($paid>$total+0.001)throw new RuntimeException('Amount paid cannot exceed the sale total.');
        $q=$pdo->prepare('INSERT INTO sales(user_id,customer_id,total,amount_paid,payment_method,notes) VALUES(?,?,?,?,?,?)');$q->execute([$uid,$customerId,$total,$paid,$method,$notes?:null]);$saleId=(int)$pdo->lastInsertId();
        $line=$pdo->prepare('INSERT INTO sale_items(sale_id,product_id,product_name,quantity,unit_price,unit_cost) VALUES(?,?,?,?,?,?)');
        $stock=$pdo->prepare('UPDATE products SET quantity=quantity-? WHERE id=? AND user_id=? AND quantity>=?');
        foreach($locked as $p){$line->execute([$saleId,$p['id'],$p['name'],$p['sale_qty'],$p['selling_price'],$p['cost_price']]);$stock->execute([$p['sale_qty'],$p['id'],$uid,$p['sale_qty']]);if($stock->rowCount()!==1)throw new RuntimeException('Stock changed while saving. Please retry the sale.');$before=(int)$p['quantity'];$after=$before-(int)$p['sale_qty'];$m=$pdo->prepare("INSERT INTO inventory_movements(user_id,product_id,product_name,movement_type,quantity_change,quantity_before,quantity_after,reference_type,reference_id,note) VALUES(?,?,?,'sale',?,?,?,'sale',?,?)");$m->execute([$uid,$p['id'],$p['name'],-(int)$p['sale_qty'],$before,$after,$saleId,'Stock deducted for sale #'.$saleId]);}
        $pdo->commit(); audit_log($pdo, 'sale_recorded', 'sale', $saleId, 'Sale total '.number_format($total,2,'.','').' NGN; items '.count($locked)); flash('Sale #'.$saleId.' recorded. Total: '.money($total)); redirect('receipt.php?id='.$saleId);
      } catch(Throwable $ex){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$ex instanceof RuntimeException?$ex->getMessage():'Unable to record sale. Please retry.';}
    }
}
$q=$pdo->prepare('SELECT id,name,selling_price,quantity FROM products WHERE user_id=? AND quantity>0 ORDER BY name');$q->execute([$uid]);$products=$q->fetchAll();
$q=$pdo->prepare('SELECT id,name FROM customers WHERE user_id=? ORDER BY name');$q->execute([$uid]);$customers=$q->fetchAll();
$q=$pdo->prepare('SELECT s.*,c.name customer FROM sales s LEFT JOIN customers c ON c.id=s.customer_id WHERE s.user_id=? ORDER BY s.id DESC LIMIT 100');$q->execute([$uid]);$sales=$q->fetchAll();
$pageTitle='Sales'; require __DIR__.'/includes/header.php'; ?>
<div class="page-heading"><div><h1 class="h3 fw-bold mb-1">Sales</h1><p class="muted mb-0">Build a multi-product cart. Stock updates only when the whole sale succeeds.</p></div></div>
<?php foreach($errors as $err):?><div class="alert alert-danger"><?=e($err)?></div><?php endforeach;?>
<div class="card mb-4"><div class="card-body p-4"><h2 class="h5 fw-bold mb-3">New sale</h2>
<?php if(!$products):?><div class="alert alert-warning mb-0">No products with stock are available. <a href="products.php">Add products or update inventory</a> first.</div><?php else:?>
<form method="post" id="cartForm" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>">
<div class="col-md-6"><label class="form-label" for="addProduct">Add product</label><select class="form-select" id="addProduct"><option value="">Choose a product…</option><?php foreach($products as $p):?><option value="<?=(int)$p['id']?>" data-name="<?=e($p['name'])?>" data-price="<?=e((string)$p['selling_price'])?>" data-stock="<?=(int)$p['quantity']?>"><?=e($p['name'])?> — <?=money($p['selling_price'])?> (stock <?=(int)$p['quantity']?>)</option><?php endforeach;?></select></div>
<div class="col-md-6"><label class="form-label" for="customerId">Customer</label><select class="form-select" id="customerId" name="customer_id"><option value="">Walk-in customer</option><?php foreach($customers as $c):?><option value="<?=(int)$c['id']?>"><?=e($c['name'])?></option><?php endforeach;?></select></div>
<div class="col-12"><div class="table-responsive"><table class="table align-middle" id="cartTable"><thead><tr><th>Product</th><th style="width:130px">Quantity</th><th>Unit price</th><th>Subtotal</th><th></th></tr></thead><tbody id="cartBody"><tr id="emptyCart"><td colspan="5" class="text-center text-secondary py-4">No products added yet.</td></tr></tbody><tfoot><tr><th colspan="3" class="text-end">Sale total</th><th id="cartTotal">₦0.00</th><th></th></tr></tfoot></table></div></div>
<div class="col-md-3"><label class="form-label">Payment method</label><select class="form-select" name="payment_method" id="paymentMethod"><option value="cash">Cash</option><option value="transfer">Bank transfer</option><option value="pos">POS</option><option value="credit">Credit</option><option value="other">Other</option></select></div>
<div class="col-md-3"><label class="form-label">Amount paid (₦)</label><input class="form-control" type="number" min="0" step="0.01" name="amount_paid" id="amountPaid" required value="0"></div>
<div class="col-md-6"><label class="form-label">Notes (optional)</label><input class="form-control" name="notes" maxlength="255" placeholder="e.g. transfer reference"></div>
<div class="col-12"><button class="btn btn-primary">Save sale & update stock</button></div></form><?php endif;?></div></div>
<div class="card"><div class="card-body"><h2 class="h5 fw-bold mb-3">Recent sales</h2><div class="table-responsive"><table class="table"><thead><tr><th>Sale</th><th>Customer</th><th>Payment</th><th>Total</th><th>Paid</th><th>Balance</th><th>Date</th><th></th></tr></thead><tbody><?php foreach($sales as $s):?><tr><td>#<?=(int)$s['id']?></td><td><?=e($s['customer']?:'Walk-in')?></td><td><span class="badge text-bg-light"><?=e(ucfirst($s['payment_method']))?></span></td><td><?=money($s['total'])?></td><td><?=money($s['amount_paid'])?></td><td class="<?=((float)$s['total']>(float)$s['amount_paid']?'text-danger':'text-success')?>"><?=money((float)$s['total']-(float)$s['amount_paid'])?></td><td><?=date('d M Y H:i',strtotime($s['created_at']))?></td><td><a class="btn btn-sm btn-outline-primary" href="receipt.php?id=<?=(int)$s['id']?>">Receipt</a></td></tr><?php endforeach;?></tbody></table><?php if(!$sales):?><div class="empty-state">No sales recorded yet.</div><?php endif;?></div></div></div>
<script>
(()=>{const select=document.getElementById('addProduct'),body=document.getElementById('cartBody'),totalEl=document.getElementById('cartTotal'),paid=document.getElementById('amountPaid'),method=document.getElementById('paymentMethod');const cart=new Map();const fmt=n=>new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN'}).format(n);function render(){body.innerHTML='';let total=0;if(!cart.size){body.innerHTML='<tr><td colspan="5" class="text-center text-secondary py-4">No products added yet.</td></tr>';}cart.forEach((it,id)=>{const sub=it.price*it.qty;total+=sub;const tr=document.createElement('tr');tr.innerHTML=`<td><div class="fw-semibold"></div><small class="text-secondary"></small><input type="hidden" name="items[${id}]" value="${it.qty}"></td><td><input class="form-control form-control-sm cart-qty" type="number" min="1" max="${it.stock}" value="${it.qty}" aria-label="Quantity for ${it.name}"></td><td>${fmt(it.price)}</td><td>${fmt(sub)}</td><td><button type="button" class="btn btn-sm btn-outline-danger">Remove</button></td>`;tr.querySelector('.fw-semibold').textContent=it.name;tr.querySelector('small').textContent='Stock available: '+it.stock;tr.querySelector('.cart-qty').addEventListener('change',e=>{const q=parseInt(e.target.value,10);if(!Number.isInteger(q)||q<1||q>it.stock){e.target.value=it.qty;return;}it.qty=q;render();});tr.querySelector('button').addEventListener('click',()=>{cart.delete(id);render();});body.appendChild(tr);});totalEl.textContent=fmt(total);if(paid.dataset.touched!=='1')paid.value=(method.value==='credit'?0:total).toFixed(2);}
select?.addEventListener('change',()=>{const o=select.selectedOptions[0],id=select.value;if(!id)return;const stock=Number(o.dataset.stock),it=cart.get(id);if(it){if(it.qty<stock)it.qty++;}else cart.set(id,{name:o.dataset.name,price:Number(o.dataset.price),stock,qty:1});select.value='';render();});paid?.addEventListener('input',()=>paid.dataset.touched='1');method?.addEventListener('change',()=>{paid.dataset.touched='';render();});document.getElementById('cartForm')?.addEventListener('submit',e=>{if(!cart.size){e.preventDefault();alert('Add at least one product.');}});render();})();
</script><?php require __DIR__.'/includes/footer.php';?>
